#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    string s;
    cin >> n >> k >> s;

    queue<string> q;
    unordered_set<string> visited;
    visited.reserve(k * 2 + 1);

    q.push(s);
    visited.insert(s);

    long long answer = 0;
    int count = 1;

    while (!q.empty() && count < k) {
        string current = q.front();
        q.pop();

        for (int i = 0; i < (int)current.size() && count < k; ++i) {
            string next = current.substr(0, i) + current.substr(i + 1);

            if (visited.insert(next).second) {
                q.push(next);
                answer += n - (int)next.size();
                ++count;
            }
        }
    }

    cout << (count < k ? -1 : answer);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    string s;
    cin >> n >> k >> s;

    vector<array<long long, 26>> dp(n + 1);

    for (char ch : s) {
        int c = ch - 'a';
        for (int len = n; len >= 1; --len) {
            long long ways = 0;

            if (len == 1) {
                ways = 1;
            } else {
                for (int last = 0; last < 26; ++last) {
                    ways = min(k, ways + dp[len - 1][last]);
                }
            }

            dp[len][c] = ways;
        }
    }

    long long remaining = k;
    long long answer = 0;

    for (int len = n; len >= 1 && remaining > 0; --len) {
        long long count = 0;
        for (int c = 0; c < 26; ++c) {
            count = min(k, count + dp[len][c]);
        }

        long long take = min(remaining, count);
        answer += take * (n - len);
        remaining -= take;
    }

    if (remaining > 0) {
        --remaining;
        answer += n;
    }

    cout << (remaining == 0 ? answer : -1);
    return 0;
}

