    long long remaining = k;
    long long answer = 0;

    for (int len = n; len >= 0 && remaining > 0; --len) {
        long long take = min(remaining, count[len]);
        answer += take * (n - len);
        remaining -= take;
    }

    cout << (remaining == 0 ? answer : -1);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    string s;
    cin >> n >> k >> s;

    using i128 = __int128_t;

    vector<vector<i128>> dp(n + 1, vector<i128>(n + 1, 0));
    vector<int> last(256, -1);

    dp[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        unsigned char c = s[i - 1];

        for (int len = 0; len <= i; ++len) {
            dp[i][len] = dp[i - 1][len];

            if (len > 0) {
                dp[i][len] += dp[i - 1][len - 1];

                if (last[c] != -1) {
                    dp[i][len] -= dp[last[c]][len - 1];
                }
            }
        }

        last[c] = i - 1;
    }

    long long remaining = k;
    i128 answer = 0;

    for (int len = n; len >= 0 && remaining > 0; --len) {
        long long take = dp[n][len] >= remaining
                             ? remaining
                             : static_cast<long long>(dp[n][len]);

        answer += static_cast<i128>(take) * (n - len);
        remaining -= take;
    }

    if (remaining > 0) {
        cout << -1;
        return 0;
    }

    if (answer == 0) {
        cout << 0;
        return 0;
    }

    string result;
    while (answer > 0) {
        result.push_back('0' + answer % 10);
        answer /= 10;
    }

    reverse(result.begin(), result.end());
    cout << result;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    string s;
    cin >> n >> k >> s;

    vector<array<int, 26>> nextPos(n + 1);
    nextPos[n].fill(-1);

    for (int i = n - 1; i >= 0; --i) {
        nextPos[i] = nextPos[i + 1];
        nextPos[i][s[i] - 'a'] = i;
    }

    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1));
    for (int i = 0; i <= n; ++i) {
        dp[i][0] = 1;
    }

    for (int len = 1; len <= n; ++len) {
        for (int pos = n - 1; pos >= 0; --pos) {
            long long count = 0;

            for (int c = 0; c < 26; ++c) {
                int next = nextPos[pos][c];
                if (next == -1) continue;

                long long add = dp[next + 1][len - 1];
                if (count >= k - add) {
                    count = k;
                    break;
                }
                count += add;
            }

            dp[pos][len] = count;
        }
    }

    long long remaining = k;
    long long answer = 0;

    for (int len = n; len >= 0 && remaining > 0; --len) {
        long long take = min(remaining, dp[0][len]);
        answer += take * (n - len);
        remaining -= take;
    }

    cout << (remaining == 0 ? answer : -1);
    return 0;
}

